function Beam(t){this.type="beam",t[0].addBeam(this),t[1].addBeam(this),this.vertices=[t[0]._originalPosition,t[1]._originalPosition],this.nodes=t,this.originalLength=this.getLength()}Beam.prototype.getLength=function(){return this.getVector().length()},Beam.prototype.getOriginalLength=function(){return this.originalLength},Beam.prototype.recalcOriginalLength=function(){this.originalLength=this.getVector().length()},Beam.prototype.isFixed=function(){return this.nodes[0].fixed&&this.nodes[1].fixed},Beam.prototype.getVector=function(t){return t==this.nodes[1]?this.vertices[0].clone().sub(this.vertices[1]):this.vertices[1].clone().sub(this.vertices[0])},Beam.prototype.getK=function(){return globals.axialStiffness/this.getLength()},Beam.prototype.getD=function(){return 2*globals.percentDamping*Math.sqrt(this.getK()*this.getMinMass())},Beam.prototype.getNaturalFrequency=function(){return Math.sqrt(this.getK()/this.getMinMass())},Beam.prototype.getMinMass=function(){var t=this.nodes[0].getSimMass();return this.nodes[1].getSimMass()<t&&(t=this.nodes[1].getSimMass()),t},Beam.prototype.getOtherNode=function(t){return this.nodes[0]==t?this.nodes[1]:this.nodes[0]},Beam.prototype.destroy=function(){var t=this;_.each(this.nodes,function(e){e.removeBeam(t)}),this.vertices=null,this.nodes=null};